// Generated from src/registry/sources/control-ui/recipes/empty.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const emptyKnobs = [
  "--cui-empty-radius",
  "--cui-empty-background",
  "--cui-empty-border-color",
  "--cui-empty-border-width",
  "--cui-empty-border-style",
  "--cui-empty-media-radius",
  "--cui-empty-media-background",
] as const;
export type EmptyKnobStyle = Partial<Record<(typeof emptyKnobs)[number], string>>;

@layer components {
  :where([data-control-family="empty"][data-slot="root"]) {
    --cui-empty-radius: var(--radius-lg);
    --cui-empty-background: transparent;
    --cui-empty-border-color: transparent;
    --cui-empty-border-width: 0px;
    --cui-empty-border-style: solid;
    --cui-empty-media-radius: var(--radius-lg);
    --cui-empty-media-background: var(--muted);
    border: var(--cui-empty-border-width) var(--cui-empty-border-style) var(--cui-empty-border-color);
    border-radius: var(--cui-empty-radius);
    background: var(--cui-empty-background);
    box-shadow: none;
    color: var(--foreground);
    text-align: center;
    text-wrap: balance;
    gap: calc(var(--spacing) * 6);
    padding: calc(var(--spacing) * 6);
  }

  :where([data-control-family="empty"][data-slot="media"]) {
    margin-block-end: calc(var(--spacing) * 2);
    inline-size: calc(var(--spacing) * 10);
    block-size: calc(var(--spacing) * 10);
    border-radius: var(--cui-empty-media-radius);
    background: var(--cui-empty-media-background);
    color: var(--muted-foreground);
  }

  :where([data-control-family="empty"][data-slot="content"]) {
    gap: calc(var(--spacing) * 2);
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    text-wrap: balance;
  }

  :where([data-control-family="empty"][data-slot="description"]) {
    font-size: var(--text-sm);
    line-height: var(--leading-relaxed);
    color: var(--muted-foreground);
  }

  :where([data-control-family="empty"][data-slot="title"]) {
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    font-weight: var(--font-weight-medium);
    color: var(--foreground);
  }

  :where([data-control-family="empty"][data-slot="header"]) {
    gap: calc(var(--spacing) * 2);
    text-align: center;
  }
}

@property --cui-empty-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-empty-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --cui-empty-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-empty-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-empty-border-style {
  syntax: "*";
  inherits: true;
  initial-value: solid;
}

@property --cui-empty-media-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-empty-media-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

import type { ComponentProps, CSSProperties } from "react";

import type { EmptyKnobStyle } from "@/components/control-ui/knob-contracts/empty-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export type EmptyProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & EmptyKnobStyle };

export type EmptyMediaProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & EmptyKnobStyle };

export type EmptyContentProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & EmptyKnobStyle };

export type EmptyDescriptionProps = Omit<ComponentProps<"p">, "style"> & { style?: CSSProperties & EmptyKnobStyle };

export type EmptyTitleProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & EmptyKnobStyle };

export function Empty({ className, ...props }: EmptyProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="root"
      className={cn("flex min-w-0 flex-1 flex-col items-center justify-center", className)}
      {...props}
    />
  );
}

export function EmptyHeader({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & EmptyKnobStyle }) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="header"
      className={cn("flex max-w-sm flex-col items-center", className)}
      {...props}
    />
  );
}

export function EmptyMedia({ className, ...props }: EmptyMediaProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="media"
      className={cn("flex shrink-0 items-center justify-center [&>svg]:size-5 [&>svg]:shrink-0", className)}
      {...props}
    />
  );
}

export function EmptyTitle({ className, ...props }: EmptyTitleProps) {
  return <div data-control-ui="empty" data-control-family="empty" data-slot="title" className={className} {...props} />;
}

export function EmptyDescription({ className, ...props }: EmptyDescriptionProps) {
  return <p data-control-ui="empty" data-control-family="empty" data-slot="description" className={className} {...props} />;
}

export function EmptyContent({ className, ...props }: EmptyContentProps) {
  return (
    <div
      data-control-ui="empty"
      data-control-family="empty"
      data-slot="content"
      className={cn("flex w-full max-w-sm flex-col items-center justify-center", className)}
      {...props}
    />
  );
}
